def kosaraju(n, graf):
    stek = []
    korilgan = [False] * n
    def dfs1(u):
        korilgan[u] = True
        for v in graf.get(u, []):
            if not korilgan[v]: dfs1(v)
        stek.append(u)

    for i in range(n):
        if not korilgan[i]: dfs1(i)

    teskari = defaultdict(list)
    for u in graf:
        for v in graf[u]: teskari[v].append(u)

    korilgan = [False] * n
    scc_lar = []
    def dfs2(u, komp):
        korilgan[u] = True
        komp.append(u)
        for v in teskari[u]:
            if not korilgan[v]: dfs2(v, komp)

    while stek:
        u = stek.pop()
        if not korilgan[u]:
            k = []
            dfs2(u, k)
            scc_lar.append(k)
    return scc_lar

print("Kosaraju SCC:", kosaraju(3, {0: [1], 1: [2], 2: [0]}))
