    BigInt(std::string r) : raqamlar(r) {}
    BigInt operator+(const BigInt& b) const {
        std::string res = "";
        int i = raqamlar.length() - 1, j = b.raqamlar.length() - 1, dilda = 0;
        while (i >= 0 || j >= 0 || dilda) {
            int sum = dilda;
            if (i >= 0) sum += raqamlar[i--] - '0';
