int hisoblaRPN(const std::string& exp) {
    std::stack<int> st;
    std::stringstream ss(exp);
    std::string token;
    while (ss >> token) {
        if (token == "+" || token == "*") {
            int b = st.top(); st.pop();
            int a = st.top(); st.pop();
            st.push((token == "+") ? (a + b) : (a * b));
        } else {
            st.push(std::stoi(token));
        }
    }
    return st.top();
}

int main() {
