class RingBuffer {
    int buf[4];
    int head = 0, tail = 0, count = 0;
public:
    bool push(int val) {
        if (count == 4) return false;
        buf[tail] = val;
        tail = (tail + 1) % 4;
        count++;
        return true;
    }
    int pop() {
        if (count == 0) return -1;
        int val = buf[head];
        head = (head + 1) % 4;
        count--;
        return val;
    }
};

