int quickSelect(std::vector<int>& v, int l, int r, int k) {
    if (l == r) return v[l];
    int pivot = v[r];
    int pIdx = l;
    for (int i = l; i < r; ++i) {
        if (v[i] <= pivot) std::swap(v[i], v[pIdx++]);
    }
    std::swap(v[pIdx], v[r]);
    if (pIdx == k) return v[pIdx];
    if (pIdx > k) return quickSelect(v, l, pIdx - 1, k);
    return quickSelect(v, pIdx + 1, r, k);
}

