int maxRectangleArea(const std::vector<int>& h) {
    std::stack<int> s;
    int maxA = 0, n = h.size();
    for (int i = 0; i <= n; ++i) {
        int cur = (i == n) ? 0 : h[i];
        while (!s.empty() && cur < h[s.top()]) {
            int balandlik = h[s.top()]; s.pop();
            int eni = s.empty() ? i : i - s.top() - 1;
            maxA = std::max(maxA, balandlik * eni);
        }
        s.push(i);
    }
    return maxA;
}

