#include <iostream>
#include <vector>
#include <queue>

const int INF = 1e9;

struct Edge {
    int to;
    int weight;
};

std::vector<int> dijkstra(int start, int n, const std::vector<std::vector<Edge>>& adj) {
    std::vector<int> dist(n, INF);
    // min-heap: juftlik (masofa, tugun)
    std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::greater<std::pair<int, int>>> pq;

    dist[start] = 0;
    pq.push({0, start});

    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();

        if (d > dist[u]) continue;

        for (const auto& edge : adj[u]) {
            int v = edge.to;
            int w = edge.weight;

            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }
    return dist;
}

int main() {
    int V = 5;
    std::vector<std::vector<Edge>> adj(V);
    adj[0].push_back({1, 4});
    adj[0].push_back({2, 1});
    adj[2].push_back({1, 2});
    adj[1].push_back({3, 1});
    adj[2].push_back({3, 5});
    adj[3].push_back({4, 3});

    auto distances = dijkstra(0, V, adj);
    for (int i = 0; i < V; ++i) {
        std::cout << "0 dan " << i << " gacha eng qisqa yo'l: " << distances[i] << "\n";
    }

    return 0;
}
