    if (bellmanFord(0, V, edges, dist)) {
        std::cout << "0 dan masofalar: ";
        for (int i = 0; i < V; ++i) std::cout << dist[i] << " ";
        std::cout << "\n";
    } else {
        std::cout << "Grafda manfiy sikl topildi!\n";
    }

    return 0;
}
