class MinHeap {
private:
    std::vector<int> heap;

    void siftUp(int i) {
        while (i > 0) {
            int parent = (i - 1) / 2;
            if (heap[i] < heap[parent]) {
                std::swap(heap[i], heap[parent]);
                i = parent;
            } else break;
        }
    }

    void siftDown(int i) {
        int n = heap.size();
        while (2 * i + 1 < n) {
            int left = 2 * i + 1;
            int right = 2 * i + 2;
            int smallest = left;
            if (right < n && heap[right] < heap[left]) smallest = right;

            if (heap[i] > heap[smallest]) {
                std::swap(heap[i], heap[smallest]);
                i = smallest;
            } else break;
        }
    }

public:
    void push(int val) {
        heap.push_back(val);
        siftUp(heap.size() - 1);
    }

    int popMin() {
        if (heap.empty()) throw std::runtime_error("Heap bo'sh!");
        int minVal = heap[0];
        heap[0] = heap.back();
        heap.pop_back();
        if (!heap.empty()) siftDown(0);
        return minVal;
    }

    bool empty() const { return heap.empty(); }
};

int main() {
    MinHeap mh;
    for (int x : {35, 12, 45, 2, 8, 19}) {
        mh.push(x);
    }

    std::cout << "MinHeap elementlari chiqarilishi: ";
    while (!mh.empty()) {
        std::cout << mh.popMin() << " ";
    }
    std::cout << std::endl;

    return 0;
}
