#include <iostream>
#include <string>
#include <vector>

std::vector<int> computeLPS(const std::string& pat) {
    int m = pat.size();
    std::vector<int> lps(m, 0);
    int len = 0;
    int i = 1;

    while (i < m) {
        if (pat[i] == pat[len]) {
            len++;
            lps[i] = len;
            i++;
        } else {
            if (len != 0) {
                len = lps[len - 1];
            } else {
                lps[i] = 0;
                i++;
            }
        }
    }
    return lps;
}

std::vector<int> KMPSearch(const std::string& pat, const std::string& txt) {
    std::vector<int> matches;
    int m = pat.size();
    int n = txt.size();
    auto lps = computeLPS(pat);

    int i = 0, j = 0;
    while (i < n) {
        if (pat[j] == txt[i]) {
            i++;
            j++;
        }
        if (j == m) {
            matches.push_back(i - j);
            j = lps[j - 1];
        } else if (i < n && pat[j] != txt[i]) {
            if (j != 0) {
                j = lps[j - 1];
            } else {
                i++;
            }
        }
    }
    return matches;
}

int main() {
    std::string txt = "ABABDABACDABABCABAB";
    std::string pat = "ABABCABAB";

    auto res = KMPSearch(pat, txt);
    std::cout << "Topilgan indekslar: ";
    for (int idx : res) std::cout << idx << " ";
    std::cout << std::endl;

    return 0;
}
