unsigned int getHighestSetBit(unsigned int n) {
    if (n == 0) return 0;
    // Barcha o'ngdagi bitlarni 1 ga aylantiramiz (bit-smearing)
    n |= (n >> 1);
    n |= (n >> 2);
    n |= (n >> 4);
    n |= (n >> 8);
