    std::cout << "Arena ajratgan double: " << *pDouble << "\n";
    std::cout << "Ishlatilgan xotira: " << arena.used() << " bayt\n";

    arena.reset();
    std::cout << "Reset qilingach: " << arena.used() << " bayt\n";

    return 0;
}
