std::vector<std::string_view> splitWords(std::string_view str) {
    std::vector<std::string_view> tokens;
    size_t start = 0;
    while (start < str.size()) {
        size_t end = str.find(' ', start);
        if (end == std::string_view::npos) {
            tokens.push_back(str.substr(start));
            break;
