float Q_rsqrt(float number) {
    long i;
    float x2, y;
    const float threehalfs = 1.5F;

    x2 = number * 0.5F;
    y  = number;
    i  = *(long*)&y;                       // Float baytlarini long deb o'qiymiz
    i  = 0x5f3759df - (i >> 1);            // Sehrli raqam va bit siljish
    y  = *(float*)&i;
    y  = y * (threehalfs - (x2 * y * y));  // Nyuton-Rafson iteratsiyasi

    return y;
}

