// 4 ta 2-bitli sonni parallel qo'shish (Bit-sliced adder)
// x = [a0, a1], y = [b0, b1]
void bitSlicedAdd(uint8_t a0, uint8_t a1, uint8_t b0, uint8_t b1,
                  uint8_t& s0, uint8_t& s1, uint8_t& cout) {
    // 0-darajali to'liq qo'shgich
    s0 = a0 ^ b0;
    uint8_t c0 = a0 & b0;

    // 1-darajali qo'shgich
    s1 = a1 ^ b1 ^ c0;
    cout = (a1 & b1) | (c0 & (a1 ^ b1));
}

