    uint8_t a0 = 0b1010; // 4 ta sonning 0-bitlari
    uint8_t a1 = 0b1100; // 4 ta sonning 1-bitlari
    uint8_t b0 = 0b0110;
    uint8_t b1 = 0b1010;

