std::map<std::string, std::string> parseSimpleJSON(const std::string& json) {
    std::map<std::string, std::string> result;
    bool inKey = false, inVal = false;
    std::string key = "", val = "";

    for (size_t i = 0; i < json.size(); ++i) {
        char c = json[i];
        if (c == '"') {
            if (!inKey && val.empty()) {
                inKey = true;
                key = "";
            } else if (inKey) {
                inKey = false;
            } else if (!inVal) {
                inVal = true;
                val = "";
