                result[key] = val;
            }
        } else if (c == ':' && !inKey) {
            // qiymat boshlanadi
        } else if (c == ',' || c == '}') {
            if (!key.empty() && !val.empty()) {
                result[key] = val;
                key = "";
                val = "";
            }
        } else {
            if (inKey) key += c;
            else if (inVal) val += c;
        }
    }
    return result;
}

