void stableSoftmax(std::vector<float>& logits) {
    float maxVal = *std::max_element(logits.begin(), logits.end());
    float sumExp = 0.0f;

    for (float& x : logits) {
        x = std::exp(x - maxVal); // Max ayirish orqali exp to'lib toshmaydi
        sumExp += x;
    }

    for (float& x : logits) {
        x /= sumExp;
    }
}

int main() {
