    std::cout << "\nINT8 data: ";
    for (int8_t q : qt.qdata) std::cout << (int)q << " ";
    std::cout << "\nTiklandi:  ";
    for (float f : restored) std::cout << f << " ";
    std::cout << "\n";

    return 0;
}
