void bubbleSort(List<int> list) {
  int n = list.length;
  for (int i = 0; i < n - 1; ++i) {
    bool almashdi = false;
    for (int j = 0; j < n - i - 1; ++j) {
      if (list[j] > list[j + 1]) {
        int temp = list[j];
        list[j] = list[j + 1];
        list[j + 1] = temp;
        almashdi = true;
      }
    }
    if (!almashdi) break; // Agar almashish bo'lmasa, saralangan
  }
}

void main() {
  List<int> sonlar = [64, 34, 25, 12, 22, 11, 90];
  bubbleSort(sonlar);
  print("Bubble Sort natijasi: $sonlar");
}
```

