void selectionSort(List<int> list) {
  int n = list.length;
  for (int i = 0; i < n - 1; ++i) {
    int minIdx = i;
    for (int j = i + 1; j < n; ++j) {
      if (list[j] < list[minIdx]) minIdx = j;
    }
    int temp = list[minIdx];
    list[minIdx] = list[i];
    list[i] = temp;
  }
}

void main() {
  List<int> sonlar = [29, 10, 14, 37, 13];
  selectionSort(sonlar);
  print("Selection Sort natijasi: $sonlar");
}
