List<int> mergeSorted(List<int> a, List<int> b) {
  List<int> res = [];
  int i = 0, j = 0;

  while (i < a.length && j < b.length) {
    if (a[i] <= b[j]) {
      res.add(a[i++]);
    } else {
      res.add(b[j++]);
    }
  }

  while (i < a.length) res.add(a[i++]);
  while (j < b.length) res.add(b[j++]);

  return res;
}

void main() {
  List<int> l1 = [1, 3, 5, 7];
  List<int> l2 = [2, 4, 6, 8, 10];

  print("Birlashtirilgan: ${mergeSorted(l1, l2)}");
}
