T retry<T>(T Function() operation, {int maxAttempts = 3}) {
  int attempts = 0;
  while (true) {
    try {
      attempts++;
      return operation();
    } catch (e) {
      if (attempts >= maxAttempts) {
        rethrow;
      }
      print("Urinish $attempts muvaffaqiyatsiz. Qayta urinilmoqda...");
    }
  }
}

