T? findMode<T>(List<T> list) {
  if (list.isEmpty) return null;
  Map<T, int> counts = {};
  for (T item in list) {
    counts[item] = (counts[item] ?? 0) + 1;
  }

  T mode = list[0];
  int maxCount = 0;
  for (var entry in counts.entries) {
    if (entry.value > maxCount) {
      maxCount = entry.value;
      mode = entry.key;
    }
  }
  return mode;
}

