(int, int)? twoSumSorted(List<int> numbers, int target) {
  int left = 0;
  int right = numbers.length - 1;

  while (left < right) {
    int sum = numbers[left] + numbers[right];
    if (sum == target) return (left, right);
    if (sum < target) left++;
    else right--;
  }
  return null;
}

