  double _balance = 0.0;
  final List<String> _history = [];

  Account(this.owner, double initial) {
    if (initial > 0) deposit(initial);
  }

  void deposit(double amount) {
    _balance += amount;
    _history.add("+$amount so'm kiritildi. Balans: $_balance");
