List<double> movingAverage(List<double> data, int window) {
  List<double> result = [];
  for (int i = 0; i <= data.length - window; i++) {
    var sub = data.sublist(i, i + window);
    double avg = sub.reduce((a, b) => a + b) / window;
    result.add(avg);
  }
  return result;
}

