Stream<(A, B)> zipStreams<A, B>(Stream<A> s1, Stream<B> s2) async* {
  var it1 = StreamIterator(s1);
  var it2 = StreamIterator(s2);

  while (await it1.moveNext() && await it2.moveNext()) {
    yield (it1.current, it2.current);
  }
}

