Stream<T> throttleStream<T>(Stream<T> stream, Duration duration) {
  var controller = StreamController<T>();
  bool blok = false;

  stream.listen((data) {
    if (!blok) {
      controller.add(data);
      blok = true;
      Timer(duration, () => blok = false);
    }
  }, onDone: controller.close);

  return controller.stream;
}

