Stream<double> lowPassFilter(Stream<double> input, double alpha) async* {
  double? prev;
  await for (var val in input) {
    if (prev == null) {
      prev = val;
    } else {
      prev = alpha * val + (1 - alpha) * prev;
    }
    yield prev;
  }
}

void main() async {
  var shovqinli = Stream.fromIterable([10.0, 50.0, 12.0, 15.0]);
