  // qator 0: (+1*5) + (-1*3) = 2.0
  // qator 1: (0*5) + (+1*3) = 3.0
  var res = await Isolate.run(() => bitNetGemvFonda(([1, -1, 0, 1], [5.0, 3.0], 2, 2)));

