import 'dart:math';

List<double> positionalEncoding(int pos, int dModel) {
  List<double> pe = List.filled(dModel, 0.0);
  for (int i = 0; i < dModel; i += 2) {
    double div = pow(10000, i / dModel).toDouble();
    pe[i] = sin(pos / div);
    if (i + 1 < dModel) {
      pe[i + 1] = cos(pos / div);
    }
  }
  return pe;
}

