(double, double) applyRope2D(double x0, double x1, double theta) {
  double cosT = cos(theta);
  double sinT = sin(theta);
  // [cos, -sin; sin, cos] * [x0; x1]
  double rot0 = x0 * cosT - x1 * sinT;
  double rot1 = x0 * sinT + x1 * cosT;
  return (rot0, rot1);
