class JsonGrammarValidator {
  static bool validateJsonResponse(String text) {
    text = text.trim();
    if (!text.startsWith('{') || !text.endsWith('}')) {
      return false;
    }
    // Qavslar balansi
    int braceCount = 0;
    for (int i = 0; i < text.length; i++) {
      if (text[i] == '{') braceCount++;
      if (text[i] == '}') braceCount--;
      if (braceCount < 0) return false;
    }
    return braceCount == 0;
  }
}

void main() {
