  String brokenJson = '{"ism": "Anvar", "yosh": 25';

  print('Matn 1 mosmi? ${JsonGrammarValidator.validateJsonResponse(validJson)}');
  print('Matn 2 mosmi? ${JsonGrammarValidator.validateJsonResponse(brokenJson)}');
}
