fn palindrom_tekshir(s: &str) -> bool {
    let bayt = s.as_bytes();
    let mut i = 0;
    let mut j = bayt.len().saturating_sub(1);

    while i < j {
        if bayt[i] != bayt[j] {
            return false;
        }
        i += 1;
        j -= 1;
    }
    true
}

