fn min_max<T: PartialOrd + Copy>(royxat: &[T]) -> Option<(T, T)> {
    if royxat.is_empty() { return None; }
    let mut min = royxat[0];
    let mut max = royxat[0];

    for &item in &royxat[1..] {
        if item < min { min = item; }
        if item > max { max = item; }
    }
    Some((min, max))
}

fn main() {
