    let mut bufer = [0u8; 100];
    let n = cr.read(&mut bufer)?;

    println!("O'qilgan matn: {}", std::str::from_utf8(&bufer[..n]).unwrap());
    println!("Jami o'qilgan baytlar soni: {}", cr.hisob);
    Ok(())
}
