func binarQidiruv(arr []int, maqsad int) int {
	chap := 0
	ong := len(arr) - 1

	for chap <= ong {
		orta := chap + (ong-chap)/2

		if arr[orta] == maqsad {
			return orta // Topilgan indeks
		}
		if arr[orta] < maqsad {
			chap = orta + 1
		} else {
			ong = orta - 1
		}
	}
	return -1 // Topilmadi
}

