package main

import "fmt"

func bubbleSort(arr []int) {
	n := len(arr)
	for i := 0; i < n-1; i++ {
		almashdimi := false
		for j := 0; j < n-i-1; j++ {
			if arr[j] > arr[j+1] {
				arr[j], arr[j+1] = arr[j+1], arr[j]
				almashdimi = true
			}
		}
		if !almashdimi {
			break // Allaqachon tartiblangan bo'lsa to'xtash
		}
	}
}

