package main

import (
	"fmt"
	"math/rand"
)

func shuffle(arr []int) {
	r := rand.New(rand.NewSource(42)) // Deterministik seed namoyish uchun
	for i := len(arr) - 1; i > 0; i-- {
		j := r.Intn(i + 1)
		arr[i], arr[j] = arr[j], arr[i]
	}
}

func main() {
	kartalar := []int{1, 2, 3, 4, 5, 6, 7}
	shuffle(kartalar)
	fmt.Println("Aralashtirilgan:", kartalar)
}
