import "fmt"

func transpose(m [][]int) [][]int {
	qatorlar := len(m)
	ustunlar := len(m[0])

	natija := make([][]int, ustunlar)
	for i := range natija {
		natija[i] = make([]int, qatorlar)
	}

	for i := 0; i < qatorlar; i++ {
		for j := 0; j < ustunlar; j++ {
