func topJuftlik(arr []int, target int) (int, int, bool) {
	chap := 0
	ong := len(arr) - 1

	for chap < ong {
		yigindi := arr[chap] + arr[ong]
		if yigindi == target {
			return arr[chap], arr[ong], true
		}
		if yigindi < target {
