type PrefixSum struct {
	pref []int
}

func NewPrefixSum(arr []int) *PrefixSum {
	pref := make([]int, len(arr)+1)
	for i, x := range arr {
		pref[i+1] = pref[i] + x
	}
	return &PrefixSum{pref: pref}
}

func (p *PrefixSum) Query(L, R int) int {
	return p.pref[R+1] - p.pref[L]
