func insertBST(root *BSTNode, val int) *BSTNode {
	if root == nil {
		return &BSTNode{Val: val}
	}
	if val < root.Val {
		root.Left = insertBST(root.Left, val)
	} else {
		root.Right = insertBST(root.Right, val)
	}
	return root
}

