import "fmt"

type Node struct {
	val  int
	next *Node
}

func reverseList(head *Node) *Node {
	var prev *Node
	curr := head

	for curr != nil {
		nextTemp := curr.next
		curr.next = prev
		prev = curr
		curr = nextTemp
	}
	return prev
}

func main() {
	n3 := &Node{val: 3}
	n2 := &Node{val: 2, next: n3}
	n1 := &Node{val: 1, next: n2}

