package main

import "fmt"

type Node struct {
	val  int
	next *Node
}

func mergeSorted(l1, l2 *Node) *Node {
	dummy := &Node{}
	tail := dummy

	for l1 != nil && l2 != nil {
		if l1.val < l2.val {
			tail.next = l1
			l1 = l1.next
		} else {
			tail.next = l2
			l2 = l2.next
		}
		tail = tail.next
	}

	if l1 != nil {
		tail.next = l1
	} else {
		tail.next = l2
	}
	return dummy.next
}

func main() {
	l1 := &Node{val: 1, next: &Node{val: 3}}
	l2 := &Node{val: 2, next: &Node{val: 4}}

	merged := mergeSorted(l1, l2)
	for p := merged; p != nil; p = p.next {
		fmt.Printf("%d ", p.val)
	}
	fmt.Println()
}
