type TreeNode struct {
	val   int
	left  *TreeNode
	right *TreeNode
}

func maxDepth(root *TreeNode) int {
	if root == nil {
		return 0
	}
	chap := maxDepth(root.left)
	ong := maxDepth(root.right)
	if chap > ong {
		return chap + 1
	}
	return ong + 1
}

