	runelar := []rune(shifr)
	for i := range runelar {
		runelar[i] -= s.siljish
	}
	return string(runelar)
}

func main() {
	sh := Shifrlagich{siljish: 3}
	maxfiy := sh.Shifrla("GOLANG")
	asl := sh.Deshifrla(maxfiy)

	fmt.Println("Shifrlangan:", maxfiy)
	fmt.Println("Ochilgan:", asl)
}
