func Insert[T cmp.Ordered](root *BSTNode[T], val T) *BSTNode[T] {
	if root == nil {
		return &BSTNode[T]{Val: val}
	}
	if val < root.Val {
		root.Left = Insert(root.Left, val)
	} else {
		root.Right = Insert(root.Right, val)
	}
	return root
}

func main() {
