	ts.Qo'sh(22.5) // Harorat
	ts.Qo'sh(23.0)
	ts.Qo'sh(24.5)

	fmt.Printf("Time-Series o'lchovlari soni: %d, O'rtacha: %.2f°C\n",
		len(ts.nuqtalar), ts.Ortacha())
}
