#include <stdio.h>
#include <stdarg.h>

void mini_printf(const char *format, ...) {
    va_list args;
    va_start(args, format);

    for (const char *p = format; *p != '\0'; p++) {
        if (*p != '%') {
            putchar(*p);
            continue;
        }
        p++; // '%' dan keyingi belgiga o'tish
        switch (*p) {
            case 'd': {
                int i = va_arg(args, int);
                printf("%d", i);
                break;
            }
            case 's': {
                char *s = va_arg(args, char *);
                fputs(s, stdout);
                break;
            }
            case '%':
                putchar('%');
                break;
        }
    }
    va_end(args);
}

int main(void) {
