int binar_qidiruv(const int arr[], int n, int nishon) {
    int chap = 0, ong = n - 1;
    while (chap <= ong) {
        int orta = chap + (ong - chap) / 2;
        if (arr[orta] == nishon) return orta;
        if (arr[orta] < nishon) chap = orta + 1;
        else ong = orta - 1;
    }
    return -1;
