void bubble_sort(int arr[], int n) {
    for (int i = 0; i < n - 1; i++) {
        bool almashdimi = false;
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                int temp = arr[j];
                arr[j] = arr[j + 1];
