int asosiy_element(const int arr[], int n) {
    int nomzod = arr[0];
    int ovoz = 1;

    for (int i = 1; i < n; i++) {
        if (arr[i] == nomzod) {
            ovoz++;
        } else {
            ovoz--;
            if (ovoz == 0) {
                nomzod = arr[i];
                ovoz = 1;
            }
        }
    }
    return nomzod;
}

