char* mening_strtok(char *str, char ajratuvchi) {
    static char *keyingi = NULL;
    if (str != NULL) {
        keyingi = str;
    }
    if (keyingi == NULL || *keyingi == '\0') {
        return NULL;
    }

    char *boshlanish = keyingi;
    while (*keyingi != '\0') {
        if (*keyingi == ajratuvchi) {
            *keyingi = '\0'; // Satrni tugatish
            keyingi++;       // Keyingi token boshiga o'tish
            return boshlanish;
        }
        keyingi++;
    }
    return boshlanish;
}

