typedef struct {
    int *data;
    size_t size;
    size_t capacity;
} Vektor;

void vektor_push(Vektor *v, int qiymat) {
    if (v->size == v->capacity) {
        size_t yangi_cap = (v->capacity == 0) ? 2 : v->capacity * 2;
        int *yangi_data = (int*)realloc(v->data, yangi_cap * sizeof(int));
