typedef struct {
    int *elementlar;
    int tepa;
    int sigim;
} DinamikStek;

void push(DinamikStek *s, int val) {
    if (s->tepa == s->sigim) {
        s->sigim = (s->sigim == 0) ? 2 : s->sigim * 2;
        s->elementlar = (int*)realloc(s->elementlar, s->sigim * sizeof(int));
    }
