void cmd_stop(void)  { printf("[ACTION]: Tizim to'xtatildi!\n"); }
void cmd_reset(void) { printf("[ACTION]: Tizim qayta yuklandi!\n"); }
void cmd_info(void)  { printf("[ACTION]: Tizim holati: Barcha modullar normal.\n"); }

