#include <stdio.h>

typedef void (*Listener)(int);

Listener obunachilar[4] = { NULL };

void subscribe(Listener l) {
    for (int i = 0; i < 4; i++) {
        if (obunachilar[i] == NULL) {
            obunachilar[i] = l;
            return;
        }
    }
}

void unsubscribe(Listener l) {
    for (int i = 0; i < 4; i++) {
        if (obunachilar[i] == l) {
            obunachilar[i] = NULL;
            return;
        }
    }
}

void notify(int val) {
    for (int i = 0; i < 4; i++) {
        if (obunachilar[i] != NULL) {
            obunachilar[i](val);
