typedef struct DNode {
    int data;
    struct DNode *prev;
    struct DNode *next;
} DNode;

void push_back_dlist(DNode **head, int val) {
    DNode *new_node = (DNode*)malloc(sizeof(DNode));
    new_node->data = val;
    new_node->next = NULL;

    if (*head == NULL) {
        new_node->prev = NULL;
        *head = new_node;
        return;
    }

    DNode *curr = *head;
    while (curr->next != NULL) curr = curr->next;

    curr->next = new_node;
    new_node->prev = curr;
}

int main(void) {
    DNode *head = NULL;
    push_back_dlist(&head, 10);
    push_back_dlist(&head, 20);
    push_back_dlist(&head, 30);

    // Oldinga yurish
    printf("Oldinga: ");
    DNode *c = head, *last = NULL;
    while (c) {
        printf("%d <-> ", c->data);
        last = c;
        c = c->next;
    }
    printf("NULL\n");

    // Orqaga yurish
    printf("Orqaga:  ");
    while (last) {
        printf("%d <-> ", last->data);
        DNode *tmp = last;
        last = last->prev;
        free(tmp);
    }
    printf("NULL\n");
    return 0;
}
