#include <stdio.h>
#include <ctype.h>

int hisobla_postfix(const char *exp) {
    int stack[64];
    int top = -1;

    for (int i = 0; exp[i]; i++) {
        if (isspace(exp[i])) continue;

        if (isdigit(exp[i])) {
            stack[++top] = exp[i] - '0';
        } else {
            int b = stack[top--];
            int a = stack[top--];
            switch (exp[i]) {
                case '+': stack[++top] = a + b; break;
                case '-': stack[++top] = a - b; break;
                case '*': stack[++top] = a * b; break;
                case '/': stack[++top] = a / b; break;
            }
        }
    }
    return stack[top];
}

int main(void) {
    // (5 + 3) * 2 = 16
    const char *rpn = "5 3 + 2 *";
    printf("Postfix '%s' natijasi: %d\n", rpn, hisobla_postfix(rpn));
    return 0;
}
```

