#include <stdio.h>

#define Q_CAP 5

typedef struct {
    int data[Q_CAP];
    int head;
    int tail;
    int count;
} Queue;

void init_queue(Queue *q) { q->head = 0; q->tail = 0; q->count = 0; }
int is_q_empty(Queue *q) { return q->count == 0; }
int is_q_full(Queue *q) { return q->count == Q_CAP; }

void enqueue(Queue *q, int val) {
    if (is_q_full(q)) return;
    q->data[q->tail] = val;
    q->tail = (q->tail + 1) % Q_CAP;
    q->count++;
}

int dequeue(Queue *q) {
    if (is_q_empty(q)) return -1;
    int val = q->data[q->head];
    q->head = (q->head + 1) % Q_CAP;
    q->count--;
    return val;
}

int main(void) {
    Queue q;
    init_queue(&q);

    enqueue(&q, 10);
    enqueue(&q, 20);
    enqueue(&q, 30);

    printf("Navbatdan chiqish (FIFO): %d\n", dequeue(&q));
    printf("Navbatdan chiqish (FIFO): %d\n", dequeue(&q));

    enqueue(&q, 40);
    enqueue(&q, 50);

    while (!is_q_empty(&q)) {
        printf("%d ", dequeue(&q));
    }
    printf("\n");
    return 0;
}
```

