#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define TABLE_SIZE 10

typedef struct Entry {
    char key[32];
    int val;
    struct Entry *next;
} Entry;

Entry* table[TABLE_SIZE] = { NULL };

unsigned int hash(const char *k) {
    unsigned int h = 0;
    while (*k) h = (h * 31) + *k++;
    return h % TABLE_SIZE;
}

void ht_put(const char *key, int val) {
    unsigned int idx = hash(key);
    Entry *e = (Entry*)malloc(sizeof(Entry));
    strcpy(e->key, key);
    e->val = val;
    e->next = table[idx];
    table[idx] = e;
}

int ht_get(const char *key, int *val) {
    unsigned int idx = hash(key);
    Entry *e = table[idx];
    while (e) {
        if (strcmp(e->key, key) == 0) {
            *val = e->val;
            return 1;
        }
        e = e->next;
    }
    return 0;
}

int main(void) {
    ht_put("olma", 15000);
    ht_put("nok", 25000);

    int narx;
    if (ht_get("olma", &narx)) {
        printf("Olma narxi: %d so'm\n", narx);
    }
    return 0;
}
