typedef struct {
    int *data;
    size_t size;
    size_t cap;
} Vector;

void vec_init(Vector *v) {
    v->size = 0;
    v->cap = 2;
    v->data = (int *)malloc(v->cap * sizeof(int));
}

void vec_push(Vector *v, int val) {
    if (v->size == v->cap) {
        v->cap *= 2;
        v->data = (int *)realloc(v->data, v->cap * sizeof(int));
    }
    v->data[v->size++] = val;
}

void vec_free(Vector *v) { free(v->data); }

