    Vector v;
    vec_init(&v);

    for (int i = 1; i <= 5; i++) vec_push(&v, i * 10);

    printf("Vector sig'imi: %zu, Elementlar: %zu\n", v.cap, v.size);
    for (size_t i = 0; i < v.size; i++) printf("%d ", v.data[i]);
    printf("\n");

    vec_free(&v);
    return 0;
}
