    if (s->ruxsatlar > 0) s->ruxsatlar--;
}

void sem_ber(Semafor *s) {
    s->ruxsatlar++;
}

int main(void) {
    Semafor s = { 3 }; // 3 ta bo'sh o'rin

    sem_kut(&s); // 1-oqim kirdi
    sem_kut(&s); // 2-oqim kirdi
