uint8_t spi_transfer_byte(uint8_t out_byte, uint8_t slave_in) {
    uint8_t in_byte = 0;
    // Har bir taktda MOSI orqali bit chiqadi, MISO orqali kiradi
    for (int i = 7; i >= 0; i--) {
        uint8_t bit_out = (out_byte >> i) & 1;
        uint8_t bit_in  = (slave_in >> i) & 1;
        in_byte |= (bit_in << i);
