uint16_t sensor_filter(uint16_t raw) {
    static uint32_t sum = 0;
    static uint16_t samples[4] = {0};
    static int idx = 0;

    sum -= samples[idx];
    samples[idx] = raw;
    sum += raw;
    idx = (idx + 1) % 4;
    return (uint16_t)(sum / 4);
}

