<head>
  <meta charset="UTF-8">
  <title>Toggle Switch</title>
  <style>
    .switch {
      position: relative;
      display: inline-block;
      width: 50px;
      height: 26px;
    }
    .switch input { opacity: 0; width: 0; height: 0; }
    .slider {
      position: absolute;
      inset: 0;
      background-color: #cbd5e1;
      border-radius: 26px;
      cursor: pointer;
      transition: 0.3s;
    }
    .slider::before {
      position: absolute;
      content: "";
      height: 20px;
      width: 20px;
      left: 3px;
      bottom: 3px;
      background-color: white;
      border-radius: 50%;
      transition: 0.3s;
    }
    input:checked + .slider { background-color: #3b82f6; }
    input:checked + .slider::before { transform: translateX(24px); }
  </style>
</head>
<body>
