{
    static void Main()
    {
        int[] massiv = [ 29, 10, 14, 37, 13 ];
        int n = massiv.Length;

        for (int i = 0; i < n - 1; i++)
        {
            int minIndeks = i;
            for (int j = i + 1; j < n; j++)
            {
                if (massiv[j] < massiv[minIndeks])
