{
    static bool Hisobla(in decimal asosiyNarx, out decimal chegirma, ref decimal balans, params ReadOnlySpan<decimal> qoshimchalar)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(asosiyNarx);

