        foreach (var q in qoshimchalar) jamiQoshimcha += q;

        decimal umumiy = asosiyNarx + jamiQoshimcha;
        chegirma = umumiy > 1_000_000m ? umumiy * 0.10m : 0m;
        decimal tolanadigan = umumiy - chegirma;

        if (balans >= tolanadigan)
