    static Action Debounce(Action amal, int kutishVaqtiMs)
    {
        CancellationTokenSource? cts = null;

        return () =>
        {
            cts?.Cancel();
            cts = new CancellationTokenSource();
            var token = cts.Token;

            Task.Delay(kutishVaqtiMs, token).ContinueWith(t =>
            {
                if (!t.IsCanceled) amal();
            }, token);
        };
    }

