    private readonly SemaphoreSlim semafor;

    public YuklovchiDvigatel(int maxParallelizm)
    {
        semafor = new SemaphoreSlim(maxParallelizm);
    }

    public async Task<string> YuklashAsync(string resursNom, CancellationToken ct)
