function reverseNumber(num: number): number {
  let reversed = 0;
  let remaining = Math.abs(num);

  while (remaining > 0) {
    const lastDigit = remaining % 10;
    reversed = reversed * 10 + lastDigit;
    remaining = Math.floor(remaining / 10);
  }

  return num < 0 ? -reversed : reversed;
}

