function getFibonacciMemo() {
  const memo: Record<number, number> = { 0: 0, 1: 1 };

  function fib(n: number): number {
    if (n in memo) {
      return memo[n];
    }
    memo[n] = fib(n - 1) + fib(n - 2);
    return memo[n];
  }

