class WeakCache<T extends object> {
  private ref: WeakRef<T> | null = null;

  set(value: T): void {
    this.ref = new WeakRef(value);
  }

  get(): T | null {
    if (!this.ref) return null;
    const derefValue = this.ref.deref();
    return derefValue !== undefined ? derefValue : null;
  }
}

