function monitorEventLoopLag(intervalMs: number = 50, callback: (lag: number) => void): () => void {
  let expectedTime = Date.now() + intervalMs;

  const timer = setInterval(() => {
    const now = Date.now();
    const lag = Math.max(0, now - expectedTime);
