function findMax<T extends Comparable<T>>(items: T[]): T | undefined {
    if (items.length === 0) return undefined;
    let max = items[0];
    for (let i = 1; i < items.length; i++) {
        if (items[i].compareTo(max) > 0) {
            max = items[i];
        }
    }
    return max;
}

