class TaskQueue {
    private queue: (() => Promise<void>)[] = [];
    private running = false;

    add(task: () => Promise<void>) {
        this.queue.push(task);
        this.processNext();
    }

    private async processNext() {
        if (this.running || this.queue.length === 0) return;
        this.running = true;
        const task = this.queue.shift()!;
        await task();
        this.running = false;
        this.processNext();
    }
}

