    -- Ichki blok boshlanishi
    DECLARE
        KOMISSIYA_FOIZ CONSTANT NUMERIC := 0.015; -- 1.5% o'zgarmas komissiya
        v_sof_summa NUMERIC;
        asosiy_xabar TEXT := 'Ichki blokda hisoblandi'; -- Tashqi o'zgaruvchini shadow qilish
