        v_natija := ROUND(v_sof_summa * p_kurs, 2);
        RAISE NOTICE 'Holat: %, Sof valyuta: %', asosiy_xabar, v_sof_summa;
    END;
    -- Ichki blok tugashi

    RETURN 'Muvaffaqiyat: ' || v_natija || ' so''m';
END;
$$;

