RETURNS NUMERIC
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
    v_faktorial NUMERIC := 1;
    v_sanagich INT := 1;
BEGIN
    IF n < 0 THEN
        RAISE EXCEPTION 'Manfiy son uchun faktorial aniqlanmagan: %', n;
    ELSIF n = 0 THEN
        RETURN 1;
    END IF;

    LOOP
        v_faktorial := v_faktorial * v_sanagich;
        v_sanagich := v_sanagich + 1;

        EXIT WHEN v_sanagich > n;
    END LOOP;

    RETURN v_faktorial;
END;
$$;

