CREATE OR REPLACE FUNCTION aniqla_ekub(a INT, b INT)
RETURNS INT
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
    v_a INT := ABS(a);
    v_b INT := ABS(b);
    v_vaqtincha INT;
BEGIN
    WHILE v_b <> 0 LOOP
        v_vaqtincha := v_b;
        v_b := v_a % v_b;
        v_a := v_vaqtincha;
    END LOOP;

    RETURN v_a;
END;
$$;

